CREATE TABLE events (id TEXT PRIMARY KEY, name TEXT NOT NULL, currency TEXT NOT NULL CHECK(currency IN ('EUR','GBP','USD')), budget_minor INTEGER NOT NULL CHECK(budget_minor >= 0), event_date TEXT, revision INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, sample INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE teams (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), name TEXT NOT NULL, code TEXT NOT NULL, quantities TEXT NOT NULL CHECK(json_valid(quantities)), revision INTEGER NOT NULL DEFAULT 1);
CREATE UNIQUE INDEX team_event_name ON teams(event_id, name);
CREATE TABLE fixtures (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), team_a TEXT NOT NULL REFERENCES teams(id), team_b TEXT NOT NULL REFERENCES teams(id), pair_key TEXT NOT NULL, label TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, CHECK(team_a != team_b));
CREATE UNIQUE INDEX fixture_event_pair ON fixtures(event_id, pair_key);
CREATE TABLE assets (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), kind TEXT NOT NULL, relative_path TEXT NOT NULL, sha256 TEXT NOT NULL, mime TEXT NOT NULL, permission TEXT NOT NULL CHECK(json_valid(permission)), revision INTEGER NOT NULL DEFAULT 1, deleted_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE designs (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), name TEXT NOT NULL, colour TEXT NOT NULL, primary_hex TEXT NOT NULL, secondary_hex TEXT NOT NULL, pattern TEXT NOT NULL, image_kind TEXT NOT NULL DEFAULT 'illustration', asset_id TEXT REFERENCES assets(id), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE shirt_options (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), team_id TEXT NOT NULL REFERENCES teams(id), design_id TEXT NOT NULL REFERENCES designs(id), owned INTEGER NOT NULL, unit_minor INTEGER NOT NULL CHECK(unit_minor >= 0), setup_minor INTEGER NOT NULL CHECK(setup_minor >= 0), minimum_order INTEGER NOT NULL CHECK(minimum_order >= 0), stock TEXT NOT NULL CHECK(json_valid(stock)), available INTEGER NOT NULL DEFAULT 1, seller TEXT NOT NULL, price_date TEXT NOT NULL, illustrative INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE previews (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), design_id TEXT NOT NULL REFERENCES designs(id), person_asset_id TEXT NOT NULL REFERENCES assets(id), reference_asset_id TEXT NOT NULL REFERENCES assets(id), output_asset_id TEXT REFERENCES assets(id), input_hash TEXT NOT NULL, api_version TEXT NOT NULL, parameters TEXT NOT NULL CHECK(json_valid(parameters)), provider_task_id TEXT, status TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, stale INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX preview_inputs ON previews(input_hash, api_version);
CREATE TABLE shirt_regions (id TEXT PRIMARY KEY, preview_id TEXT NOT NULL REFERENCES previews(id), polygon TEXT NOT NULL CHECK(json_valid(polygon)), transform_version TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE reviews (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), fixture_id TEXT NOT NULL REFERENCES fixtures(id), option_a TEXT NOT NULL REFERENCES shirt_options(id), option_b TEXT NOT NULL REFERENCES shirt_options(id), status TEXT NOT NULL, reviewer TEXT NOT NULL, reason TEXT NOT NULL, evidence TEXT NOT NULL CHECK(json_valid(evidence)), revision INTEGER NOT NULL DEFAULT 1, stale_reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE planning_runs (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), event_revision INTEGER NOT NULL, status TEXT NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), total_minor INTEGER, stale INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE exports (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES planning_runs(id), snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), created_at TEXT NOT NULL);
CREATE TABLE jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, status TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), provider_task_id TEXT, lease_until TEXT, attempts INTEGER NOT NULL DEFAULT 0, estimated_units INTEGER NOT NULL DEFAULT 0, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX jobs_status ON jobs(status, lease_until);
CREATE TABLE usage_ledger (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), estimated_units INTEGER NOT NULL, confirmed_units INTEGER, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX usage_job ON usage_ledger(job_id);
CREATE TABLE activity (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, detail TEXT NOT NULL CHECK(json_valid(detail)), created_at TEXT NOT NULL);
CREATE INDEX activity_event ON activity(event_id, created_at);
